(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};
  out.statusBefore = [...document.querySelectorAll('.tb-actions button')].map((b) => b.textContent.trim()).find((t) => t.includes('识别设置')) || null;

  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.includes('识别设置'))?.click();
  await sleep(1200);
  const modes = [...document.querySelectorAll('.ai-modes .ai-mode-title')].map((e) => e.textContent.trim());
  out.modes = modes;
  out.modeCards = document.querySelectorAll('.ai-modes > *').length;

  // ① 本机识别凭据：填假 Key 保存
  const cards = [...document.querySelectorAll('.ai-modes > *')];
  cards.find((c) => c.textContent.includes('本机'))?.click();
  await sleep(900);
  const inputs = [...document.querySelectorAll('.ai-modal input')];
  out.inputsAfterLocalMode = inputs.length;
  const keyInput = inputs.find((i) => i.type === 'password');
  const urlInput = inputs.find((i) => (i.placeholder || '').includes('http'));
  out.canEditKey = !!keyInput;
  if (keyInput) {
    setV(urlInput, 'https://example.invalid/v1');
    setV(keyInput, 'sk-this-is-a-fake-test-key-000111');
    [...document.querySelectorAll('.ai-modal .ai-btn-primary')].find((b) => b.textContent.trim() === '保存')?.click();
    await sleep(1200);
  }
  document.querySelector('.ai-close')?.click();
  await sleep(700);
  out.statusAfterLocal = [...document.querySelectorAll('.tb-actions button')].map((b) => b.textContent.trim()).find((t) => t.includes('识别设置')) || null;

  // ② 生成老师配置码
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.includes('识别设置'))?.click();
  await sleep(1000);
  const cards2 = [...document.querySelectorAll('.ai-modes > *')];
  cards2.find((c) => c.textContent.includes('老师'))?.click();
  await sleep(900);
  const tInputs = [...document.querySelectorAll('.ai-modal input')];
  setV(tInputs.find((i) => (i.placeholder || '').includes('workers.dev')) || tInputs[0], 'https://demo.workers.dev');
  setV(tInputs.find((i) => (i.placeholder || '').includes('class')) || tInputs[1], 'class-2026-token');
  [...document.querySelectorAll('.ai-modal .ai-btn-soft')][0]?.click();
  await sleep(900);
  const code = document.querySelector('.ai-modal textarea')?.value || '';
  out.teacherCodeLen = code.length;
  out.teacherCodePrefix = code.slice(0, 4);
  out.codeHasFakeKey = /sk-this-is-a-fake/.test(code);
  out.codeHasToken = /class-2026-token/.test(code);

  // ③ 切回手动模式
  document.querySelector('.ai-close')?.click();
  await sleep(600);
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.includes('识别设置'))?.click();
  await sleep(1000);
  [...document.querySelectorAll('.ai-modes > *')].find((c) => c.textContent.includes('手动'))?.click();
  await sleep(900);
  document.querySelector('.ai-close')?.click();
  await sleep(700);
  out.statusAfterManual = [...document.querySelectorAll('.tb-actions button')].map((b) => b.textContent.trim()).find((t) => t.includes('识别设置')) || null;

  // ④ 手动模式下工具箱功能照常
  const cards3 = [...document.querySelectorAll('.tb-project-main')];
  out.worksVisible = cards3.length;
  return JSON.stringify(out);
})()
